"use strict";(self.webpackChunkleia_docs=self.webpackChunkleia_docs||[]).push([[8817],{71056:e=>{e.exports=JSON.parse('{"tag":{"label":"designer","permalink":"/docs/tags/designer","allTagsPath":"/docs/tags","count":9,"items":[{"id":"teachers/designer/activities","title":"Activities","description":"The advanced and admin roles. The Activities entry of the sidebar is hidden for instructors.","permalink":"/docs/teachers/designer/activities"},{"id":"teachers/designer/widgets","title":"Code editor widget","description":"Every role that can edit a problem can add widgets. Widgets only run on OpenAI models, because LEIA uses tool calls to read, edit and test the code.","permalink":"/docs/teachers/designer/widgets"},{"id":"teachers/designer/create-leia","title":"Create a LEIA with the AI assistant","description":"The advanced and admin roles. An instructor can follow every step but Finish LEIA will be refused, because the assistant creates a new behaviour and instructors cannot create behaviours. Instructors should use the quick start instead.","permalink":"/docs/teachers/designer/create-leia"},{"id":"contributing/designer-backend","title":"Designer Backend","description":"Repository: leia-org/leia-designer-backend","permalink":"/docs/contributing/designer-backend"},{"id":"contributing/designer-frontend","title":"Designer Frontend","description":"Repository: leia-org/leia-designer-frontend","permalink":"/docs/contributing/designer-frontend"},{"id":"teachers/designer/components-reference","title":"Persona, Problem and Behaviour fields","description":"Every role can edit personas and problems. Editing a behaviour is reserved to the advanced and admin roles.","permalink":"/docs/teachers/designer/components-reference"},{"id":"teachers/designer/test-leia","title":"Test a LEIA","description":"Every role can test any LEIA it can see, with its own keys or with the system keys.","permalink":"/docs/teachers/designer/test-leia"},{"id":"teachers/designer/index","title":"The LEIA library","description":"Every role can browse, test and design from the library. Add to activity and Quick replication appear only for the advanced and admin roles. Deleting is reserved to the owner of the LEIA and to administrators.","permalink":"/docs/teachers/designer/"},{"id":"teachers/designer/supervisor","title":"The supervisor","description":"Every role that can finish a LEIA can enable its supervisor. It needs an OpenAI key.","permalink":"/docs/teachers/designer/supervisor"}],"unlisted":false}}')}}]);